'use strict';
const $=s=>document.querySelector(s);
const html=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={data:null,flow:'X',sector:'',view:'markets',saved:new Set(),page:1,pageSize:24,status:null,sources:[],benchmarks:null,production:null,news:null,companies:null,fallback:false};
try{const current=localStorage.getItem('export-edge-watchlist'),legacy=current===null?localStorage.getItem('export-legacy-watchlist'):null,s=JSON.parse(current??legacy??'[]');if(Array.isArray(s)){state.saved=new Set(s.filter(v=>typeof v==='string'));if(current===null&&legacy!==null)localStorage.setItem('export-edge-watchlist',JSON.stringify([...state.saved]));}}catch{}
const views=['markets','explorer','production','benchmarks','news','companies','watchlist','sources'];
state.productionFilters={product:'',country:'',year:'',page:1};
