state.companyFilters={query:'',country:'',role:'',activity:'',source:'',evidence:'',page:1};
const compact=v=>v==null?'Not available':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:2}).format(v);
