const number=v=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(v);
const text=v=>Array.isArray(v)?v.map(text).join('; '):typeof v==='object'?Object.entries(v??{}).map(([k,x])=>`${k}: ${text(x)}`).join('; '):String(v??'Not specified');
const date=v=>v&&Number.isFinite(new Date(v).getTime())?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/London'}):'Not yet recorded';
const safeUrl=v=>{try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const list=v=>Array.isArray(v)?v.filter(x=>x!=null).map(String):v==null?[]:[String(v)];
const csvCell=v=>{const raw=v==null?'':typeof v==='number'?String(v):String(v);const safe=typeof v==='number'?raw:/^[=+@\-\t\r]/.test(raw)?"'"+raw:raw;return `"${safe.replace(/"/g,'""')}"`;};
function downloadCsv(name,rows){const csv='\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const record=(m,y,f=state.flow)=>m.records.find(r=>+r.year===+y&&r.flow===f);
const value=(m,y,f=state.flow)=>{const v=record(m,y,f)?.value;return v!=null&&Number.isFinite(+v)?+v:null;};
const year=()=>+$('#year').value;
const growth=m=>{const a=value(m,year()),b=value(m,year()-1);return a!=null&&b>0?(a/b-1)*100:null;};
const years=()=>[...new Set(state.data.markets.flatMap(m=>m.records.map(r=>+r.year)).concat(state.data.collection?.years??state.data.years??[]))].filter(Number.isFinite).sort((a,b)=>b-a);
const delta=n=>n==null?'No comparison':`${n>0?'+':''}${n.toFixed(1)}%`;
const change=n=>`<span class="change ${n==null?'neutral':n<0?'negative':''}">${n==null?'—':n<0?'↘':'↗'} ${delta(n)}<small>vs ${year()-1}${n==null?' · unavailable':''}</small></span>`;
const bookmark=saved=>`<svg viewBox="0 0 16 20" aria-hidden="true"><path d="M3 2H13V17L8 13 3 17Z" fill="${saved?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5"/></svg>`;
const grain='<g transform="rotate(22 84 53)" fill="currentColor"><path d="M81 100V13" stroke="currentColor" stroke-width="2"/><g opacity=".35"><ellipse cx="73" cy="28" rx="5" ry="13" transform="rotate(-35 73 28)"/><ellipse cx="90" cy="39" rx="5" ry="13" transform="rotate(35 90 39)"/><ellipse cx="73" cy="50" rx="5" ry="13" transform="rotate(-35 73 50)"/><ellipse cx="90" cy="62" rx="5" ry="13" transform="rotate(35 90 62)"/><ellipse cx="73" cy="73" rx="5" ry="13" transform="rotate(-35 73 73)"/></g></g>';
const icons={coffee:'<g transform="rotate(-28 80 50)"><ellipse cx="61" cy="46" rx="24" ry="32" fill="currentColor" opacity=".22"/><path d="M63 15C38 40 82 49 57 77" stroke="currentColor" stroke-width="2" fill="none"/><ellipse cx="111" cy="57" rx="21" ry="29" fill="currentColor" opacity=".22"/></g>',cocoa:'<g transform="rotate(-30 85 55)"><ellipse cx="84" cy="55" rx="26" ry="43" fill="currentColor" opacity=".18"/><ellipse cx="84" cy="55" rx="26" ry="43" stroke="currentColor" fill="none"/><path d="M84 13Q54 55 84 97M84 13Q112 55 84 97M84 12V98" stroke="currentColor" fill="none"/></g>',oil:'<path d="M82 12C78 30 53 49 53 68A29 29 0 0 0 111 68C111 50 89 29 82 12Z" fill="currentColor" opacity=".2"/><path d="M82 12C78 30 53 49 53 68A29 29 0 0 0 111 68C111 50 89 29 82 12Z" stroke="currentColor" fill="none"/>',rice:grain,wheat:grain,pepper:'<g fill="currentColor" opacity=".3"><circle cx="62" cy="47" r="13"/><circle cx="92" cy="33" r="12"/><circle cx="110" cy="64" r="14"/><circle cx="75" cy="80" r="14"/><circle cx="46" cy="79" r="8"/></g>'};
function sourceUrl(m,y=year()){
 const matching=(m.sourceUrls??[]).find(u=>{try{return new URL(u).searchParams.get('period')===String(y);}catch{return false;}});if(matching)return safeUrl(matching);
 const u=new URL('https://comtradeapi.un.org/public/v1/preview/C/A/HS');Object.entries({period:y,reporterCode:m.code,cmdCode:m.hs,flowCode:'X,M',partnerCode:0,partner2Code:0,customsCode:'C00',motCode:0,maxRecords:500}).forEach(([k,v])=>u.searchParams.set(k,v));return u.href;
}
function sparkline(m){
 const pts=m.records.filter(r=>r.flow===state.flow&&+r.year<=year()&&r.value!=null).sort((a,b)=>a.year-b.year);if(pts.length<2)return '<div class="sparkline metric-label">Trend needs two available reporting periods.</div>';
 const vs=pts.map(r=>+r.value),min=Math.min(...vs),range=Math.max(...vs)-min||1,minYear=+pts[0].year,maxYear=+pts.at(-1).year;
 const xy=pts.map(r=>[8+(+r.year-minYear)*284/(maxYear-minYear||1),33-(+r.value-min)*25/range]),d=xy.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' '),color=vs.at(-1)>=vs[0]?'#7c9c72':'#bb977b';
 return `<svg class="sparkline" viewBox="0 0 300 43" preserveAspectRatio="none" role="img" aria-label="Annual ${state.flow==='X'?'exports':'imports'}, ${pts.map(r=>`${r.year}: ${exact(r.value)}`).join('; ')}"><path d="${d}L292,43L8,43Z" fill="${color}" opacity=".08"/><path d="${d}" stroke="${color}" stroke-width="1.5" fill="none"/>${xy.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="2" fill="${color}"/>`).join('')}</svg>`;
}
function card(m){const saved=state.saved.has(m.id),colour=icons[m.color]?m.color:'wheat';return `<article class="market-card"><div class="card-top ${colour}"><svg viewBox="0 0 160 110" aria-hidden="true">${icons[colour]}</svg><span class="category">${html(m.sector.toUpperCase())}</span><button class="save-button ${saved?'saved':''}" data-save="${html(m.id)}" aria-pressed="${saved}" aria-label="${saved?'Remove':'Save'} ${html(m.product)} in ${html(m.country)} ${saved?'from':'to'} watchlist">${bookmark(saved)}</button></div><div class="card-body"><div class="country-meta"><span>◉</span> ${html(m.country)} <span class="separator"></span> HS ${html(m.hs)}</div><h3>${html(m.product)}</h3><div class="card-metric"><div><div class="metric-label">${year()} ${state.flow==='X'?'exports to':'imports from'} world · USD</div><div class="metric-number">${compact(value(m,year()))}</div></div>${change(growth(m))}</div>${sparkline(m)}<div class="card-bottom"><span>UN Comtrade · Annual</span><button class="brief-button" data-brief="${html(m.id)}">Market brief <span>↗</span></button></div></div></article>`;}
function filtered(){const q=$('#search').value.trim().toLowerCase(),country=$('#country').value,product=$('#product').value,region=$('#region').value,available=$('#available-only').checked;return state.data.markets.filter(m=>(state.view!=='watchlist'||state.saved.has(m.id))&&(!country||m.country===country)&&(!product||m.hs===product)&&(!region||m.region===region)&&(!state.sector||m.sector===state.sector)&&(!available||value(m,year())!=null)&&(!q||`${m.product} ${m.country} ${m.region} ${m.hs} ${m.description} ${m.sector}`.toLowerCase().includes(q))).sort((a,b)=>$('#sort').value==='name'?a.product.localeCompare(b.product)||a.country.localeCompare(b.country):$('#sort').value==='growth'?(growth(b)??-Infinity)-(growth(a)??-Infinity)||a.country.localeCompare(b.country):(value(b,year())??-Infinity)-(value(a,year())??-Infinity)||a.country.localeCompare(b.country));}
function explorer(ms){return `<div class="table-wrap"><table><caption class="sr-only">${year()} ${state.flow==='X'?'exports to':'imports from'} world by reporting country and product</caption><thead><tr><th>PRODUCT / HS</th><th>REPORTER</th><th>${year()} VALUE · USD</th><th>YEAR-ON-YEAR</th><th>COLLECTED</th><th>SOURCE</th><th><span class="sr-only">Brief</span></th></tr></thead><tbody>${ms.map(m=>`<tr><td><strong>${html(m.product)}</strong><small>HS ${html(m.hs)} · ${html(m.sector)}</small></td><td>${html(m.country)}<small>${html(m.region)}</small></td><td>${exact(value(m,year()))}</td><td>${change(growth(m))}</td><td>${date(record(m,year())?.fetchedAt??record(m,year())?.retrievedAt??m.lastSuccessfulFetchAt??m.retrievedAt??state.data.retrievedAt)}</td><td><a href="${html(sourceUrl(m))}" target="_blank" rel="noopener">UN Comtrade ↗</a></td><td><button data-brief="${html(m.id)}" aria-label="Read ${html(m.product)} in ${html(m.country)} market brief">↗</button></td></tr>`).join('')}</tbody></table></div><p class="method-note">World partner · Annual current US dollars · Export downloads contain every filtered row, beyond this page.</p>`;}
function pager(total){const pages=Math.ceil(total/state.pageSize);return pages>1?`<div class="pagination"><button class="button secondary" data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Previous</button><span>Page ${state.page} of ${pages}</span><button class="button secondary" data-page="${state.page+1}" ${state.page===pages?'disabled':''}>Next →</button></div>`:'';}
function statusLabel(s){const t=String(s??'listed').replace(/[_-]/g,' ');return html(t.charAt(0).toUpperCase()+t.slice(1));}
function sourceStatus(s){return(state.status?.sourceStatus??[]).find(x=>(x.id??x.sourceId)===s.id)?.status??s.status??s.integrationStatus??'listed';}
function sourceNote(s){const runtime=(state.status?.sourceStatus??[]).find(x=>(x.id??x.sourceId)===s.id);return runtime?.detail?runtime.detail+(runtime.lastSuccessAt?' Last successful update: '+date(runtime.lastSuccessAt)+'.':''):s.statusNote??s.verification??'';}
function sources(){
 const cards=state.sources.length?state.sources.map(s=>`<article class="source-card"><div class="source-title-row"><span class="tag">${html(s.category??'RESEARCH SOURCE')}</span><span class="status-pill">${statusLabel(sourceStatus(s))}</span></div><h3>${html(s.name)}</h3><p>${html(s.description??s.purpose??(s.fields??[]).join(', '))}</p><dl class="source-mini"><dt>Coverage</dt><dd>${html(text(s.coverage))}</dd><dt>Updates</dt><dd>${html(text(s.cadence??s.frequency))}</dd><dt>Access</dt><dd>${html(text(s.access))}</dd><dt>Reuse</dt><dd>${html(text(s.license??s.licensing??s.reuse??s.terms))}</dd><dt>Tridge link</dt><dd>${html(s.tridgeRelationship??'Not established')}</dd></dl><a href="${html(safeUrl(s.url??s.homepage??s.documentationUrl))}" target="_blank" rel="noopener">Open source ↗</a>${(sourceNote(s))?`<p class="method-note">${html(sourceNote(s))}</p>`:''}</article>`).join(''):'<article class="source-card source-detail"><h3>Source registry is unavailable</h3><p>Trade data retains individual UN Comtrade links. Other source connections have not been confirmed in this view.</p></article>';
 const auto=state.status?.automaticUpdates,autoText=state.fallback?'Stored snapshot only. Hosted update status is unavailable.':auto?.enabled===true||auto?.active===true?'Scheduled cloud updates are enabled. Source release dates and reporting periods still vary.':auto?.mode==='scheduled'?'The cloud update pipeline is configured. Schedule activation has not been confirmed by this status response.':'Automatic update status has not been confirmed.';
 const production=state.production?.datasets??[];
 return `<div class="data-note source-warning"><span>ⓘ</span><p><strong>Connected data and research sources are separate.</strong> A listed source is not necessarily imported. Tridge does not publicly name all its data suppliers; proprietary reports and databases are not copied here.</p></div><div class="sources-grid">${cards}<article class="source-card source-detail"><span class="tag">COLLECTION & TIMING</span><h3>Know when the data was collected</h3><p>${html(autoText)}</p><dl class="source-mini"><dt>Trade snapshot</dt><dd>${date(state.data.retrievedAt)}</dd><dt>Last update attempt</dt><dd>${date(state.status?.lastRun?.finishedAt??state.status?.lastRun?.startedAt??state.status?.lastRun)}</dd><dt>Current catalogue</dt><dd>${number(state.data.markets.length)} country–product combinations; ${new Set(state.data.markets.map(m=>m.country)).size} countries; ${new Set(state.data.markets.map(m=>m.hs)).size} HS headings.</dd><dt>Value changes</dt><dd>Official data may be revised. Growth in trade value can reflect prices, volume or product mix; it does not alone establish rising physical demand.</dd><dt>Classification</dt><dd>HS editions are kept with observations. Customs headings may cover several varieties. Shipment-level records and named buyers require separate evidence.</dd><dt>Watchlist</dt><dd>Saved in this browser only. No cross-device account storage.</dd><dt>Reuse</dt><dd>This site remains private. Public or commercial redistribution must follow each source's terms.</dd></dl></article><article class="source-card source-detail"><span class="tag">FAOSTAT RELEASE CATALOGUE</span><h3>Production and agricultural releases</h3><p>${production.length?`${number(production.length)} official FAOSTAT dataset releases are listed. These are release metadata and download links; production quantities have not been imported into market briefs.`:'FAOSTAT release metadata is unavailable in this response. Production quantities are not shown in market briefs.'}</p>${production.length?`<div class="table-wrap"><table><thead><tr><th>DATASET</th><th>UPDATED</th><th>OFFICIAL FILE</th></tr></thead><tbody>${production.map(d=>`<tr><td>${html(d.name??d.title??d.code)}<small>${html(d.code??'')}</small></td><td>${html(d.updatedAt??'Not specified')}</td><td><a href="${html(safeUrl(d.url))}" target="_blank" rel="noopener">Download ↗</a></td></tr>`).join('')}</tbody></table></div>`:''}</article></div>`;
}
function benchmarkChart(s){const obs=(s.observations??[]).filter(o=>o.value!=null&&Number.isFinite(+o.value)).slice(-24);if(obs.length<2)return '<p class="metric-label">Not enough observations for a trend.</p>';const vs=obs.map(o=>+o.value),min=Math.min(...vs),range=Math.max(...vs)-min||1,d=obs.map((o,i)=>`${i?'L':'M'}${8+i*484/(obs.length-1)},${90-(+o.value-min)*76/range}`).join(' ');return `<svg class="benchmark-chart" viewBox="0 0 500 115" preserveAspectRatio="none" role="img" aria-label="${html(s.name)} benchmark ${html(obs[0].period)} to ${html(obs.at(-1).period)}"><path d="${d}L492,99L8,99Z" fill="#7c9c72" opacity=".1"/><path d="${d}" fill="none" stroke="#668669" stroke-width="2"/><text x="8" y="113">${html(obs[0].period)}</text><text x="492" y="113" text-anchor="end">${html(obs.at(-1).period)}</text></svg>`;}
function renderBenchmarkCards(ss){
 return `<div class="data-note source-warning"><span>ⓘ</span><p><strong>Commodity benchmarks, not supplier offers.</strong> Units, product specifications and periods differ. These prices are not automatically matched to HS values or countries.</p></div><div class="benchmark-grid">${ss.map(s=>{
  const obs=(s.observations??[]).filter(o=>o.value!=null&&Number.isFinite(+o.value)).sort((a,b)=>String(a.period).localeCompare(String(b.period))),latest=obs.at(-1),prev=obs.at(-2),pct=latest&&prev&&+prev.value!==0?(+latest.value/+prev.value-1)*100:null,unit=s.unit?(s.currency&&!String(s.unit).toUpperCase().includes(String(s.currency).toUpperCase())?String(s.currency)+' / '+s.unit:s.unit):s.currency||'Unit not specified';
  return `<article class="source-card benchmark-card"><span class="tag">${html(s.source??'Source not specified')} · ${html(s.frequency??'Frequency not specified')} · ${html(unit)}</span><h3>${html(s.name)}</h3>${s.country||s.geography||s.area?`<p class="price-geography">${html(s.country??s.geography??s.area)}</p>`:''}<div class="benchmark-value">${latest?number(latest.value):'Not available'} <small>${html(latest?.period??'')}</small></div><p>${pct==null?'No prior-period comparison.':`${delta(pct)} versus ${html(prev.period)}.`}</p>${benchmarkChart({...s,observations:obs})}<details><summary>Recent observations</summary><div class="table-wrap"><table><thead><tr><th>PERIOD</th><th>${html(unit)}</th><th>SOURCE FLAG</th></tr></thead><tbody>${obs.slice(-12).reverse().map(o=>`<tr><td>${html(o.period)}</td><td>${number(o.value)}</td><td title="${html(o.flagDescription??o.status??'')}">${html(o.flag??'—')}${o.flagDescription?`<small>${html(o.flagDescription)}</small>`:''}</td></tr>`).join('')}</tbody></table></div></details>${s.notes?`<p class="method-note">${html(text(s.notes))}</p>`:''}<p class="method-note">Collected ${date(s.retrievedAt??state.benchmarks.retrievedAt)}</p><a href="${html(safeUrl(s.sourceUrl))}" target="_blank" rel="noopener">Official source ↗</a></article>`;
 }).join('')}</div>`;
}
function viewPager(kind,total,page,size=24){const pages=Math.max(1,Math.ceil(total/size));return pages>1?`<div class="pagination"><button class="button secondary" data-discovery-page="${kind}" data-target-page="${page-1}" ${page<=1?'disabled':''}>← Previous</button><span>Page ${page} of ${pages}</span><button class="button secondary" data-discovery-page="${kind}" data-target-page="${page+1}" ${page>=pages?'disabled':''}>Next →</button></div>`:'';}
function selectOptions(values,selected,empty){return `<option value="">${html(empty)}</option>`+[...new Set(values.filter(Boolean).map(String))].sort((a,b)=>a.localeCompare(b)).map(v=>`<option value="${html(v)}" ${v===selected?'selected':''}>${html(v)}</option>`).join('');}
function connectionNotes(dataset){const errors=list(dataset?.errors).filter(Boolean);const details=[...(dataset?.errors??[]).filter(e=>!(e?.source==='in-eic-approved'&&(dataset?.statuses??[]).some(s=>s.id==='in-eic-approved'&&s.refreshWarning))).map(e=>typeof e==='string'?e:e.source==='in-eic-approved'?'India approval register: automatic updates are unavailable; unexpired dated records are retained.':`${e.source??e.sourceId??'Source'}: ${e.error??e.message??'Update unavailable'}`),...(dataset?.statuses??[]).filter(s=>s.refreshWarning).map(s=>s.id==='in-eic-approved'?'India approval register: dated snapshot only. Check the original approval before relying on a listing.':`${s.id}: ${s.refreshWarning}`)];return errors.length||details.length?`<p class="method-note connection-note">Some sources could not be refreshed. Saved data is retained where available. ${html(details.join(' · '))}</p>`:'';}
function benchmarkSource(s){return String(s.source??s.publisher??'Not specified');}
function filteredBenchmarks(){const f=state.benchmarkFilters,q=f.query.trim().toLowerCase();return(state.benchmarks?.series??[]).filter(s=>(!f.source||benchmarkSource(s)===f.source)&&(!q||`${s.name} ${benchmarkSource(s)} ${s.unit??''} ${s.currency??''} ${text(s.notes??'')}`.toLowerCase().includes(q)));}
function benchmarks(){const all=state.benchmarks?.series??[],f=state.benchmarkFilters;if(!all.length)return '<div class="empty-state"><h3>Price series are not available yet.</h3><p>Trade data remains available under Markets. Prices appear after a successful source import.</p></div>';const ms=filteredBenchmarks();f.page=Math.min(f.page,Math.max(1,Math.ceil(ms.length/24)));const shown=ms.slice((f.page-1)*24,f.page*24);return `<div class="discovery-toolbar benchmark-toolbar"><label class="discovery-query">Search price series<input type="search" id="benchmark-query" value="${html(f.query)}" placeholder="Commodity, publisher or unit" aria-label="Search price series"></label><label>Publisher / source<select data-benchmark-filter="source" aria-label="Price source">${selectOptions(all.map(benchmarkSource),f.source,'All price sources')}</select></label><button class="button secondary" id="export-prices" ${ms.length?'':'disabled'}>↓ Download price CSV</button></div><p class="discovery-meta">${number(ms.length)} price series${ms.length?` · Showing ${(f.page-1)*24+1}–${(f.page-1)*24+shown.length}`:''}</p>${connectionNotes(state.benchmarks)}${ms.length?renderBenchmarkCards(shown):'<div class="empty-state"><h3>No price series match these filters.</h3><p>Try another commodity, publisher or unit.</p></div>'}${viewPager('benchmarks',ms.length,f.page)}`;}
function downloadPrices(){downloadCsv('export-edge-price-observations.csv',[['Series','Country or geography','Source','Frequency','Currency','Original unit','Period','Value','Source flag','Flag description','Collected at UTC','Source URL'],...filteredBenchmarks().flatMap(s=>(s.observations??[]).filter(o=>o.value!=null&&Number.isFinite(+o.value)).map(o=>[s.name,s.country??s.geography??s.area,s.source,s.frequency,s.currency,s.unit,o.period,+o.value,o.flag,o.flagDescription??o.status,s.retrievedAt??state.benchmarks.retrievedAt,s.sourceUrl]))]);notify('Filtered price observations downloaded with original units and source flags.');}
function filteredNews(){const f=state.newsFilters,q=f.query.trim().toLowerCase(),cutoff=f.days?Date.now()-Number(f.days)*86400000:null;return(state.news?.items??[]).filter(n=>(!f.source||String(n.publisher??n.sourceId)===f.source)&&(!f.tag||list(n.tags).includes(f.tag))&&(!cutoff||Number.isFinite(Date.parse(n.publishedAt))&&Date.parse(n.publishedAt)>=cutoff)&&(!q||`${n.title??''} ${n.summary??''} ${n.publisher??''} ${list(n.tags).join(' ')}`.toLowerCase().includes(q))).sort((a,b)=>(Date.parse(b.publishedAt)||0)-(Date.parse(a.publishedAt)||0)||String(a.title).localeCompare(String(b.title)));}
